const allItems = $input.all();
const input = allItems.length > 0 ? (allItems[0].json || {}) : {};
const confirmation = String(input.reset_confirmation || '').trim();
const expected = 'RESET_AI_AGENT_DATABASE';

if (confirmation !== expected) {
  throw new Error(
    'Reset blocked safely. Open node "01.00 - Enter Reset Confirmation (EDIT BEFORE RESET)", ' +
    'set reset_confirmation exactly to "' + expected + '", then execute Step 01 from the reset trigger. ' +
    'After the reset finishes, change the field back to the placeholder value. Current value: ' +
    (confirmation || '(empty)')
  );
}

return allItems;
